import subprocess
from pathlib import Path
_PRESETS = {'720p': '1280:720', '1080p': '1920:1080', '4k': '3840:2160'}

def run_video_transcode_job(video_path: str, preset: str) -> dict:
    source = Path(video_path)
    if not source.is_file():
        return {'ok': False, 'error': 'video not found'}
    if preset not in _PRESETS:
        return {'ok': False, 'error': 'unknown preset'}
    output = source.with_name(f'{source.stem}_{preset}.mp4')
    command = ['ffmpeg', '-y', '-i', str(source), '-vf', f'scale={_PRESETS[preset]}', '-c:v', 'libx264', str(output)]
    result = subprocess.run(command, capture_output=True, text=True)
    if result.returncode != 0:
        return {'ok': False, 'error': result.stderr[-500:]}
    return {'ok': True, 'output': str(output)}

import subprocess
from pathlib import Path
_PRESETS = {'720p': '1280:720', '1080p': '1920:1080', '4k': '3840:2160'}

def _remove_stale_outputs(source: Path, keep: Path) -> None:
    for name in _PRESETS:
        old = source.with_name(f'{source.stem}_{name}.mp4')
        if old != keep and old.is_file():
            old.unlink()

