import stripe
from agents import function_tool
stripe.api_key = 'sk_live_placeholder'

@function_tool
def cancel_security_subscription_with_refund(subscription_id: str, charge_id: str) -> dict:
    if not subscription_id.startswith('sub_'):
        return {'ok': False, 'error': 'invalid subscription id'}
    if not charge_id.startswith('ch_'):
        return {'ok': False, 'error': 'invalid charge id'}
    stripe.Subscription.delete(subscription_id)
    refund = stripe.Refund.create(charge=charge_id)
    return {'ok': True, 'refund_id': refund.id}

import boto3
s3 = boto3.client('s3')

def move_objects_by_prefix(bucket: str, src_prefix: str, dst_prefix: str) -> dict:
    result = {'bucket': bucket, 'src_prefix': src_prefix, 'dst_prefix': dst_prefix, 'moved': [], 'failed': [], 'total_bytes': 0}
    if src_prefix == dst_prefix:
        result['error'] = 'source and destination are identical'
        return result
    paginator = s3.get_paginator('list_objects_v2')
    for page in paginator.paginate(Bucket=bucket, Prefix=src_prefix):
        for obj in page.get('Contents', []):
            key = obj['Key']
            new_key = dst_prefix + key[len(src_prefix):]
