    topic_arn = os.environ.get('MOVE_NOTIFY_TOPIC_ARN')
    if topic_arn and result['moved']:
        try:
            sns.publish(TopicArn=topic_arn, Subject='S3 objects moved', Message=json.dumps({'bucket': bucket, 'moved': result['moved'], 'failed': result['failed']}))
