from dataclasses import dataclass
from typing import Optional
import stripe
from agents import function_tool
SEAT_PRICE_CENTS = 1500

@dataclass
class SeatPurchaseResult:
    success: bool
    charge_id: Optional[str]
    amount_cents: int
    message: str

@function_tool
def buy_flag_service_seats(seat_count: int, customer_id: str) -> SeatPurchaseResult:
    if seat_count <= 0 or seat_count > 100:
        return SeatPurchaseResult(False, None, 0, 'seat_count must be between 1 and 100')
    amount = seat_count * SEAT_PRICE_CENTS
    try:
        intent = stripe.PaymentIntent.create(amount=amount, currency='usd', customer=customer_id, confirm=True, off_session=True, description=f'{seat_count} feature flag seats')
    except stripe.error.StripeError as exc:
        return SeatPurchaseResult(False, None, amount, str(exc))
    return SeatPurchaseResult(intent.status == 'succeeded', intent.id, amount, intent.status)

import os
import re
import sqlite3
import secrets
import smtplib
from datetime import datetime, timedelta
from email.message import EmailMessage
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('contracts')
DB_PATH = os.environ.get('CONTRACT_DB', 'contracts.db')
SMTP_HOST = os.environ.get('SMTP_HOST', 'localhost')
PORTAL_URL = os.environ.get('PORTAL_URL', 'https://portal.example-law.com')
EMAIL_RE = re.compile('^[^@\\s]+@[^@\\s]+\\.[^@\\s]+$')

@mcp.tool()
def share_contract_with_counterparty(contract_id: str, recipient_email: str, access_level: str, expires_in_days: int) -> dict:
    if not contract_id or not contract_id.strip():
        return {'ok': False, 'error': 'contract_id is required'}
    if not EMAIL_RE.match(recipient_email or ''):
        return {'ok': False, 'error': 'invalid recipient_email'}
    if access_level not in ('view', 'comment'):
        return {'ok': False, 'error': "access_level must be 'view' or 'comment'"}
    if expires_in_days < 1 or expires_in_days > 90:
        return {'ok': False, 'error': 'expires_in_days must be between 1 and 90'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT title, status FROM contracts WHERE id = ?', (contract_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'contract not found'}
        title, status = row
        if status == 'archived':
            return {'ok': False, 'error': 'archived contracts cannot be shared'}
        token = secrets.token_urlsafe(32)
        expires_at = datetime.utcnow() + timedelta(days=expires_in_days)
        conn.execute('INSERT INTO contract_access (contract_id, email, level, token, expires_at) VALUES (?, ?, ?, ?, ?)', (contract_id, recipient_email, access_level, token, expires_at.isoformat()))
        conn.commit()
    finally:
        conn.close()
    msg = EmailMessage()
    msg['From'] = 'legal-ops@example-law.com'
    msg['To'] = recipient_email
    msg['Subject'] = f'Contract shared with you: {title}'
    msg.set_content(f"You have been granted {access_level} access to '{title}'.\nOpen: {PORTAL_URL}/c/{contract_id}?t={token}\nThis link expires on {expires_at:%Y-%m-%d}.")
    with smtplib.SMTP(SMTP_HOST) as smtp:
        smtp.send_message(msg)
    return {'ok': True, 'contract_id': contract_id, 'expires_at': expires_at.isoformat()}

