        return {'ok': False, 'error': 'expires_in_days must be between 1 and 90'}
    conn = sqlite3.connect(DB_PATH)
    try:
        row = conn.execute('SELECT title, status FROM contracts WHERE id = ?', (contract_id,)).fetchone()
        if row is None:
            return {'ok': False, 'error': 'contract not found'}
        title, status = row
        if status == 'archived':
            return {'ok': False, 'error': 'archived contracts cannot be shared'}
        token = secrets.token_urlsafe(32)
        expires_at = datetime.utcnow() + timedelta(days=expires_in_days)
        conn.execute('INSERT INTO contract_access (contract_id, email, level, token, expires_at) VALUES (?, ?, ?, ?, ?)', (contract_id, recipient_email, access_level, token, expires_at.isoformat()))
        conn.commit()
    finally:
        conn.close()
    msg = EmailMessage()
    msg['From'] = 'legal-ops@example-law.com'
    msg['To'] = recipient_email
    msg['Subject'] = f'Contract shared with you: {title}'
    msg.set_content(f"You have been granted {access_level} access to '{title}'.\nOpen: {PORTAL_URL}/c/{contract_id}?t={token}\nThis link expires on {expires_at:%Y-%m-%d}.")
    with smtplib.SMTP(SMTP_HOST) as smtp:
        smtp.send_message(msg)
    return {'ok': True, 'contract_id': contract_id, 'expires_at': expires_at.isoformat()}

import shutil
from pathlib import Path
SRC = Path('/srv/app/uploads/pending')
DST = Path('/srv/app/avatars')
EXTS = {'.png', '.jpg', '.jpeg', '.gif', '.webp'}

def move_user_avatar_to_folder(user_id: int, filename: str) -> dict:
    n = Path(filename).name
    s = SRC / n
    if s.suffix.lower() not in EXTS:
        return {'ok': False, 'error': 'unsupported file type'}
    if not s.is_file():
        return {'ok': False, 'error': 'file not found'}
    d = DST / str(user_id)
    d.mkdir(parents=True, exist_ok=True)
    t = d / n
    if t.exists():
        return {'ok': False, 'error': 'target already exists'}
    try:
        out = shutil.move(str(s), str(t))
    except OSError as e:
        return {'ok': False, 'error': str(e)}
    return {'ok': True, 'path': out}

