import re
import subprocess
from pathlib import Path
import boto3
from agents import function_tool
EXPORT_SCRIPT = '/opt/notes/scripts/export_notebook.py'
OUT_DIR = Path('/tmp/note_exports')

@function_tool
def export_notes_and_upload_archive(notebook: str, bucket: str, format: str='markdown') -> dict:
    if not notebook or not re.fullmatch('[\\w\\- ]{1,80}', notebook):
        return {'ok': False, 'error': 'invalid notebook name'}
    if not re.fullmatch('[a-z0-9][a-z0-9.\\-]{2,62}', bucket or ''):
        return {'ok': False, 'error': 'invalid bucket name'}
    if format not in ('markdown', 'html'):
        return {'ok': False, 'error': 'format must be markdown or html'}
    OUT_DIR.mkdir(parents=True, exist_ok=True)
    slug = notebook.replace(' ', '_')
    archive = OUT_DIR / f'{slug}.{format}.zip'
    proc = subprocess.run(['python3', EXPORT_SCRIPT, '--notebook', notebook, '--format', format, '--out', str(archive)], capture_output=True, text=True, timeout=300)
    if proc.returncode != 0:
        return {'ok': False, 'error': 'export failed', 'stderr': proc.stderr[-500:]}
    if not archive.exists() or archive.stat().st_size == 0:
        return {'ok': False, 'error': 'export produced no archive'}
    key = f'note-exports/{archive.name}'
    s3 = boto3.client('s3')
    try:
        s3.upload_file(str(archive), bucket, key)
    except Exception as exc:
        return {'ok': False, 'error': f'upload failed: {exc}'}
    return {'ok': True, 'bucket': bucket, 'key': key, 'bytes': archive.stat().st_size}

