import boto3
ec2 = boto3.client('ec2')

def buy_node_reserved_capacity(itype, count, max_price):
    r = ec2.describe_reserved_instances_offerings(InstanceType=itype, OfferingClass='standard', OfferingType='All Upfront', ProductDescription='Linux/UNIX', MaxDuration=31536000)
    offs = [o for o in r['ReservedInstancesOfferings'] if o['FixedPrice'] <= max_price]
    if not offs:
        return {'purchased': False, 'reason': 'no offering under max_price'}
    best = min(offs, key=lambda o: o['FixedPrice'])
    p = ec2.purchase_reserved_instances_offering(ReservedInstancesOfferingId=best['ReservedInstancesOfferingId'], InstanceCount=count, LimitPrice={'Amount': best['FixedPrice'] * count, 'CurrencyCode': 'USD'})
    return {'purchased': True, 'price': best['FixedPrice'], 'id': p['ReservedInstancesId']}

