        return {'error': 'payment failed', 'status': intent.status}
    expires = _save_subscription(camera_id, plan, intent.id)
    return {'camera_id': camera_id, 'plan': plan, 'charged_cents': PLAN_PRICES[plan], 'charge_id': intent.id, 'expires': expires}

