import sqlite3
from contextlib import closing
from mcp.server.fastmcp import FastMCP
mcp = FastMCP('calendar')
DB_PATH = 'calendar.db'

def _select_events(conn, calendar_id, start_date, end_date):
    rows = conn.execute('SELECT id, title, starts_at, ends_at FROM events WHERE calendar_id = ? AND date(starts_at) BETWEEN ? AND ? ORDER BY starts_at', (calendar_id, start_date, end_date)).fetchall()
    return [{'id': r[0], 'title': r[1], 'starts_at': r[2], 'ends_at': r[3]} for r in rows]

@mcp.tool()
def move_events_to_calendar_and_list(source_calendar_id: str, target_calendar_id: str, start_date: str, end_date: str) -> dict:
    if source_calendar_id == target_calendar_id:
        return {'error': 'source and target calendars are the same'}
    with closing(sqlite3.connect(DB_PATH)) as conn:
        target = conn.execute('SELECT 1 FROM calendars WHERE id = ?', (target_calendar_id,)).fetchone()
        if target is None:
            return {'error': f'target calendar {target_calendar_id} not found'}
        events = _select_events(conn, source_calendar_id, start_date, end_date)
        if not events:
            return {'moved': 0, 'events': []}
        ids = [e['id'] for e in events]
        placeholders = ','.join(('?' for _ in ids))
        with conn:
            conn.execute(f'UPDATE events SET calendar_id = ? WHERE id IN ({placeholders})', [target_calendar_id, *ids])
    return {'moved': len(events), 'events': events}

import re
import subprocess
import time
BIN = '/opt/bank/bin'

def _steps(interest, fees):
    steps = []
    if interest:
        steps.append(('interest', f'{BIN}/accrue_interest'))
    if fees:
        steps.append(('fees', f'{BIN}/assess_fees'))
    steps.append(('close', f'{BIN}/close_ledger'))
    return steps

def run_end_of_day_batch_jobs(business_date: str, include_interest: bool=True, include_fees: bool=True, log_path: str='/var/log/bank/eod.log') -> dict:
    if not re.fullmatch('\\d{4}-\\d{2}-\\d{2}', business_date):
        return {'status': 'error', 'message': 'invalid date'}
    results = []
    with open(log_path, 'a') as log:
        log.write(f'=== EOD {business_date} ===\n')
        for name, cmd in _steps(include_interest, include_fees):
            t0 = time.time()
            log.write(f'start {name}\n')
            try:
                p = subprocess.run([cmd, '--date', business_date], stdout=log, stderr=subprocess.STDOUT, timeout=1800)
                code = p.returncode
            except subprocess.TimeoutExpired:
                code = -1
                log.write(f'timeout {name}\n')
            elapsed = round(time.time() - t0, 2)
            results.append({'step': name, 'code': code, 'seconds': elapsed})
            log.write(f'end {name} code={code}\n')
            if code != 0:
                return {'status': 'failed', 'failed_step': name, 'steps': results}
        log.write('=== EOD complete ===\n')
    return {'status': 'ok', 'steps': results}

import os
from web3 import Web3
w3 = Web3(Web3.HTTPProvider(os.environ.get('ETH_RPC_URL', 'http://localhost:8545')))

def broadcast_eth_transfer(to_address: str, amount_eth: float, private_key: str) -> dict:
    if not Web3.is_address(to_address):
        return {'ok': False, 'error': 'invalid recipient address'}
    if amount_eth is None or amount_eth <= 0:
        return {'ok': False, 'error': 'amount must be positive'}
    if not private_key:
        return {'ok': False, 'error': 'private key required'}
    account = w3.eth.account.from_key(private_key)
    value = w3.to_wei(amount_eth, 'ether')
    gas_price = w3.eth.gas_price
    balance = w3.eth.get_balance(account.address)
    if balance < value + gas_price * 21000:
        return {'ok': False, 'error': 'insufficient balance'}
    tx = {'to': Web3.to_checksum_address(to_address), 'value': value, 'gas': 21000, 'gasPrice': gas_price, 'nonce': w3.eth.get_transaction_count(account.address), 'chainId': w3.eth.chain_id}
    signed = account.sign_transaction(tx)
    tx_hash = w3.eth.send_raw_transaction(signed.raw_transaction)
    return {'ok': True, 'tx_hash': tx_hash.hex()}

